func displayUser(name: String?) {
    if let name {
        print("User: \(name)")
    } else {
        print("No user logged in")
    }
}
displayUser(name: "Taylor")

func parsePort(input: String?) -> Int {
    guard let input, let port = Int(input) else {
        return 8080
    }
    return port
}
print(parsePort(input: "3000"))
print(parsePort(input: nil))
